      const compiled = this.ajv.compile(schema);
      this.schemaValidators.set(schema as object, compiled);
      return compiled;
    } catch (e) {
      const message = `Failed to compile schema for tool "${name}": ${(e as Error).message}`;
      log.error('tool', 'schema compilation failed', {name});
      return null;
    }

